UPDATES = {'scripts/sql/create-meta-ads-snapshot-materialization.sql', 'scripts/sql/create-meta-ads-staging-contract.sql', 'scripts/verify-meta-ads-sql-contract.ts', 'scripts/meta_ads_isolated_harness.py'}

def require(ok, message):
    if not ok:
        raise RuntimeError(message)

def sha(data):
    return hashlib.sha256(data).hexdigest()

def load_payload():
    raw = zlib.decompress(base64.b85decode(PAYLOAD))
    require(sha(raw) == PAYLOAD_SHA, 'PAYLOAD_DRIFT')
    data = json.loads(raw)
    require(set(data['updates']) == UPDATES, 'UPDATE_SCOPE_REJECTED')
    for name in data['expected']:
        p = PurePosixPath(name)
        require(not p.is_absolute() and '..' not in p.parts and p.parts[0] in ('scripts', 'src'), 'UNSAFE_PAYLOAD_PATH')
    for name, entry in data['updates'].items():
        require(sha(base64.b64decode(entry['data'], validate=True)) == entry['sha256'], 'UPDATE_HASH_DRIFT')
    return data

def verify_checkout(repo, data):
    # Verify all 27 transferred files before any edit; permit an exact rerun.
    for name, entry in data['expected'].items():
        target = repo/name
        require(not target.is_symlink() and target.resolve().is_relative_to(repo.resolve()), 'UNSAFE_REPOSITORY_PATH')
        allowed = {entry['sha256']}
        allowed.update(data['accepted_prior'].get(name, []))
        if name in data['updates']:
            allowed.add(data['updates'][name]['sha256'])
        require(target.is_file() and sha(target.read_bytes()) in allowed, 'TRANSFER_FILE_DRIFT:' + name)

def apply_updates(repo, data):
    verify_checkout(repo, data)
    for name, entry in data['updates'].items():
        target = repo/name
        target.write_bytes(base64.b64decode(entry['data']))
        require(sha(target.read_bytes()) == entry['sha256'], 'UPDATE_WRITE_FAILED:' + name)

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--workspace', type=Path, default=Path.home()/'Downloads/etrylue-meta-validation-yx3bf1m0')
    parser.add_argument('--runtime-root', type=Path, default=Path.home()/'Downloads/etrylue-meta-pg17-6')
    parser.add_argument('--run', action='store_true')
    parser.add_argument('--inspect-payload', action='store_true')
    args = parser.parse_args()
    data = load_payload()
    if args.inspect_payload:
        print(json.dumps({'payload': 'PASS', 'checked_files': len(data['expected']), 'updates': sorted(UPDATES), 'db_executions': 0}))
        return
    require(args.run, 'RUN_FLAG_REQUIRED')
    require(sys.platform == 'darwin' and sys.version_info >= (3,9) and os.geteuid() != 0, 'MAC_NON_ROOT_PYTHON_3_9_REQUIRED')
    protected = Path('/Users/damon/Projects/dashboard')
    downloads = (Path.home()/'Downloads').resolve(strict=True)
    work = args.workspace.expanduser().resolve(strict=True)
    require(work.parent == downloads and work.name.startswith('etrylue-meta-validation-')
            and not work.is_relative_to(protected) and work.stat().st_uid == os.geteuid(), 'WORKSPACE_SCOPE_REJECTED')
    repo = work/'dashboard-meta-ads-api'
    require(not repo.is_symlink() and repo.resolve().parent == work, 'REPOSITORY_SCOPE_REJECTED')
    git = '/usr/bin/git'
    def git_output(*args):
        return subprocess.check_output([git, *args], cwd=repo, text=True).strip()
    require(git_output('rev-parse','HEAD') == BASE and git_output('branch','--show-current') == 'meta-ads-api', 'BRANCH_OR_HEAD_DRIFT')
    allowed_tracked = {p for p,e in data['expected'].items() if e['base_sha256'] is not None}
    require(set(git_output('diff','HEAD','--name-only').splitlines()) == allowed_tracked, 'TRACKED_CHANGE_SCOPE_DRIFT')
    manifest = json.loads((work/'transfer-manifest.json').read_text())
    require(manifest['base'] == BASE and manifest['branch'] == 'meta-ads-api' and manifest['files'] == data['expected'], 'TRANSFER_MANIFEST_DRIFT')
    verify_checkout(repo, data)
    runtime = args.runtime_root.expanduser().resolve(strict=True)
    require(not runtime.is_relative_to(protected), 'RUNTIME_SCOPE_REJECTED')
    readiness = json.loads((runtime/'runtime-readiness.json').read_text())
    pg_bin = runtime/'install/bin'
    require(readiness['status'] == 'PASS_BINARY_PREPARATION_ONLY' and readiness['uid'] == os.geteuid()
            and readiness['pg_bin'] == str(pg_bin) and readiness['pgcrypto_control_version'] == '1.3', 'RUNTIME_READINESS_DRIFT')
    for name in ('postgres','initdb','pg_ctl','psql'):
        require(sha((pg_bin/name).read_bytes()) == readiness['versions'][name]['sha256'], 'PG_BINARY_DRIFT:' + name)
    toolchain = work/'toolchain/bin'
    for name in ('python3','node'):
        require((toolchain/name).is_file() and os.access(toolchain/name, os.X_OK), 'TOOL_MISSING:' + name)
    require((repo/'node_modules').resolve() == (work/'fixture-tools/node_modules').resolve() and
            (repo/'node_modules/tsx/package.json').is_file(), 'FIXTURE_DEPENDENCIES_MISSING')
    os.umask(0o077)
    tag = uuid.uuid4().hex[:12]
    log_path = work/('timezone-retry-' + tag + '.log')
    result_dir = work/('results-timezone-retry-' + tag)
    env = dict(os.environ, PATH=str(toolchain) + os.pathsep + os.defpath)
    print('LOG=' + str(log_path), flush=True)
    with log_path.open('x') as log:
        def run(argv):
            with subprocess.Popen([str(a) for a in argv], cwd=repo, env=env, stdout=subprocess.PIPE,
                                  stderr=subprocess.STDOUT, text=True, errors='replace') as process:
                for line in process.stdout:
                    print(line, end='', flush=True); log.write(line); log.flush()
                require(process.wait() == 0, 'LOCAL_CHECK_FAILED; log=' + str(log_path))
        try:
            apply_updates(repo, data)
            (work/('timezone-retry-' + tag + '-manifest.json')).write_text(json.dumps({
                'base': BASE, 'updates': {p:e['sha256'] for p,e in data['updates'].items()},
                'sql_candidates_changed': ['create-meta-ads-staging-contract.sql', 'create-meta-ads-snapshot-materialization.sql'], 'scope': 'isolated_candidate_only', 'previous_results_preserved': True}, indent=2)+'\n')
            run([toolchain/'node', '--import', 'tsx', 'scripts/verify-meta-ads-sql-contract.ts'])
            run([toolchain/'python3', '-B', 'scripts/verify_meta_ads_isolated_harness.py'])
            run([toolchain/'python3', '-B', 'scripts/meta_ads_isolated_harness.py', '--prepare', result_dir,
                 '--run-isolated', '--pg-bin', pg_bin, '--performance-rows', '2001'])
            result = result_dir/'runtime-result.json'
            require(result.is_file() and json.loads(result.read_text())['status'] == 'PASS', 'PASS_RESULT_MISSING')
            print('RESULT=' + str(result), flush=True)
            print('LOG=' + str(log_path), flush=True)
        except BaseException as error:
            log.write('\nRETRY_ERROR: ' + str(error) + '\n'); log.flush()
            print('FAILED. Send log: ' + str(log_path), file=sys.stderr)
            raise

if __name__ == '__main__':
    main()
